namespace Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class TemplateVersionContentHtmlVO
{
    public static function from(TemplateVersionContentHtmlVO|string $value): TemplateVersionContentHtmlVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?TemplateVersionContentHtmlVO
    {
        if ($value instanceof TemplateVersionContentHtmlVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (is_string($value)) {
            return new TemplateVersionContentHtmlVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['contentHtml'], [$value], ['string']));
            return null;
        }
    }
    private static function fromUnsafe(mixed $value): TemplateVersionContentHtmlVO
    {
        if ($value instanceof TemplateVersionContentHtmlVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof TemplateVersionContentHtmlVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly string $contentHtml
    ) {
    }
    public function value(): string
    {
        return $this->contentHtml;
    }
    public function equals(?TemplateVersionContentHtmlVO $other): bool
    {
        return $this->value() == $other?->value();
    }
}
